import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function Classes() {
  const [classes, setClasses] = useState([]);

  useEffect(() => {
    // 🟢 ඩේටාබේස් එකෙන් කාලසටහන ගන්නවා
    axios.get('http://localhost:8081/api/timetable')
      .then(res => setClasses(res.data))
      .catch(err => console.error("Error fetching classes:", err));
  }, []);

  return (
    <div style={{ padding: '50px', backgroundColor: '#f8fafc', minHeight: '100vh', textAlign: 'center' }}>
      <h2 style={{ color: '#15803d', fontSize: '32px', marginBottom: '10px' }}>Aura Pen Education</h2>
      <p style={{ color: '#64748b', marginBottom: '40px' }}>Official 2026 Class Timetable - Mirigama</p>
      
      <div style={{ maxWidth: '1000px', margin: '0 auto', backgroundColor: 'white', borderRadius: '15px', padding: '30px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '700px' }}>
          <thead style={{ backgroundColor: '#15803d', color: 'white' }}>
            <tr>
              <th style={{ padding: '15px', borderRadius: '10px 0 0 0' }}>Day</th>
              <th style={{ padding: '15px' }}>Grade</th>
              <th style={{ padding: '15px' }}>Subject</th>
              <th style={{ padding: '15px' }}>Time</th>
              <th style={{ padding: '15px', borderRadius: '0 10px 0 0' }}>Teacher</th>
            </tr>
          </thead>
          <tbody>
            {classes.length > 0 ? classes.map(c => (
              <tr key={c.id} style={{ borderBottom: '1px solid #e2e8f0' }}>
                <td style={{ padding: '15px', fontWeight: 'bold', color: '#1e293b' }}>{c.day}</td>
                <td style={{ padding: '15px', color: '#475569' }}>{c.grade}</td>
                <td style={{ padding: '15px', color: '#475569' }}>{c.subject}</td>
                <td style={{ padding: '15px', color: '#475569' }}>{c.time_slot}</td>
                <td style={{ padding: '15px', color: '#475569', fontWeight: 'bold' }}>{c.teacher}</td>
              </tr>
            )) : (
              <tr>
                <td colSpan="5" style={{ padding: '30px', textAlign: 'center', color: '#94a3b8' }}>No classes scheduled yet. Please check back later.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
